"""Reproduce BB-06–11 synthesis from the accepted, country-specific evidence.

Run from repository root. This script does not collect sources or estimate
Ozon Bank parameters. It writes explicit research hypotheses and evidence gaps.
"""
import csv, json, re
from pathlib import Path
from collections import Counter

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / 'data/b2b_banking'
DOC = ROOT / 'docs/b2b_banking'
DATE = '2026-10-10'

def read(name):
    with (DATA / f'{name}.csv').open() as f:
        r = csv.DictReader(f)
        return list(r), r.fieldnames

T = {}; H = {}
for p in DATA.glob('*.csv'):
    T[p.stem], H[p.stem] = read(p.stem)

def write_csv(name, rows, fields=None):
    with (DATA / f'{name}.csv').open('w', newline='') as f:
        w = csv.DictWriter(f, fields or H[name], lineterminator='\n')
        w.writeheader(); w.writerows(rows)

def md(name, body):
    (DOC / f'{name}.md').write_text(body.strip() + '\n')

def table(headers, rows):
    return '\n'.join(['| ' + ' | '.join(headers) + ' |',
                      '| ' + ' | '.join(['---'] * len(headers)) + ' |'] +
                     ['| ' + ' | '.join(str(x).replace('|', ', ') for x in r) + ' |' for r in rows])

